      items: [
        { id: '01', year: '2024', label: 'IN THE CONTEXT OF COP16', event: 'NaturaTech LAC Prize', description: 'NaturaTech LAC Scale-Up Studio funds and provides personalized support to a portfolio of innovative demonstrators across 6 countries and 48 allied organizations, 11 of which are indigenous or afro-descendant. Together they manage over 62,000 hectares with frontier technologies, mitigate 4.4 million tCO₂ per year, have certified 690 hectares as blue carbon and generated 77 new direct local jobs in over 40 communities.', layout: 'hero-hito', ctaUrl: 'https://www.youtube.com/watch?si=MD393RKzMzYmZzV6&v=bHeOXvmVqWo&feature=youtu.be', images: ['/assets/historias/Premio%202024/Premiacion%20Naturatech%20Lac-115.avif'] },
        { id: '02', year: '2024', label: 'ESCUELA VIVA AMAZONÍA', event: 'EXPLORA 1ST EDITION', description: 'In alliance with Escuela Viva Amazonía, an initiative of Cuencas Sagradas Amazónicas, the inaugural Explora cohort trained indigenous youth from over 20 nationalities in AI, drones, GIS and storytelling.', layout: 'split', ctaUrl: 'https://www.youtube.com/watch?v=E8RJexNqXgE', images: ['/assets/historias/Explora%201a%20edicion/DSC01063.avif', '/assets/historias/Explora%201a%20edicion/DSC01282.avif'] },
        { id: '03', year: '2024', label: 'IN THE CONTEXT OF COP16', event: 'BIODIVERSITY INVESTMENT FORUM', description: 'The first regional space where multicultural voices from Latin America and the Caribbean gathered to shape together the future of innovation for nature. By bringing together indigenous leaders, scientists, entrepreneurs and policymakers from across LAC, the Forum was a founding act of dialogue. It sowed the governance vision that would later become CEIBA.', layout: 'triple', ctaUrl: 'https://www.youtube.com/watch?v=drLfbctSeoo', images: ['/assets/historias/Foro/foro1.avif', '/assets/historias/Foro/750_7637.avif', '/assets/historias/Foro/750_7696.avif'] },
        { id: '04', year: '2024', label: 'IN THE CONTEXT OF COP16', event: 'Presentation of the Minga Jaguar', description: 'The first biocultural alliance in the region guided by the spirit of the jaguar and indigenous peoples leadership. The Minga Jaguar Alliance was born across 6 countries —Mexico, Costa Rica, Ecuador, Peru, Colombia and Brazil— weaving a shared governance and monitoring network to protect jaguar biocorridors.', layout: 'full', ctaUrl: 'https://www.youtube.com/watch?v=lyO3V67DHi4', images: ['/assets/historias/1er%20Encuentro%20Minga/Panel%20Jaguar_Flii_1.avif'] },
        { id: '05', year: '2025', label: 'Minga Jaguar', event: 'First Gathering', description: 'For the first time, the guardians of the jaguar corridor gathered in the same space and built a shared roadmap. Held in the Yucatan Peninsula, the gathering convened alliance members from across the transboundary corridor to align monitoring protocols, drive AI adoption and co-design the biocultural governance model for the jaguar\'s entire range.', layout: 'hero-hito', ctaUrl: 'https://www.youtube.com/watch?v=coyQBGsMKow', images: ['/assets/historias/1er%20Encuentro%20Minga/Panel%20Jaguar_Flii_1.avif'] },
        { id: '06', year: '2025', label: 'Cross-border Gathering', event: 'Bridging Bioregions', description: 'The first EU–LAC cross-border gathering for regenerative innovation. Co-led with SIDA and the Stockholm Resilience Centre at the Beijer Institute / Royal Swedish Academy of Sciences, Bridging Regions connected LAC\'s biocultural innovation ecosystem with European sustainability, technology and financing networks.', layout: 'split', ctaUrl: '', images: ['/assets/historias/Explora%201a%20edicion/DSC01063.avif', '/assets/historias/Explora%201a%20edicion/DSC01282.avif'] },
        { id: '07', year: '2025', label: 'Escuela Viva Amazonía', event: 'Explora 2nd Edition', description: 'Across its two editions, Explora has trained over 100 young indigenous leaders from more than 20 nationalities in Ecuador and Peru.', layout: 'triple', ctaUrl: '', images: ['/assets/historias/Explora%201a%20edicion/DSC01063.avif', '/assets/historias/Explora%201a%20edicion/DSC01282.avif', '/assets/historias/Foro/foro1.avif'] },
        { id: '08', year: '2025', label: 'Summit', event: 'Ceiba 2025', description: 'Over 100 leaders from 17 countries gathered in a governance council. Multicultural, intergenerational and multisectoral —from territorial indigenous leaders to funds, entrepreneurs and civil society— with the goal of enabling LAC\'s continental architecture for collective intelligence on biodiversity and natural capital.', layout: 'full', ctaUrl: '', images: ['/assets/historias/Premio%202024/Premiacion%20Naturatech%20Lac-115.avif'] },
      ],
